// Smoke test: synthetic patient generated by the surrogate itself, then fit at several checkpoints.
const GL = require('./load_core');
const S = GL.schema, M = GL.modules.marrow, TI = GL.modules.tumor_immune;
const truth = { R: 0.5, g: 120, q: 1 / 60, f0: 0.02, tau: 1, N0: 3.4, PLT0: 210 };
const base = { patient_id: 'SYN1', demographics: { age: 62, sex: 'F' }, product: 'A', costim: 'CD28', history: { prior_lines: 3, prior_asct: 0, prior_bendamustine: 1, months_since_last_chemo: 4 }, bridging: 'none', ld: { flu_total: 90, cy_total: 1500, dose_reduced: 0 }, crs: { grade: 3, onset_day: 3, end_day: 9 }, mutations: { tested: true, variants: [] }, observations: [], events: [{ type: 'tocilizumab', day_start: 4, day_end: 4 }, { type: 'gcsf', day_start: 24, day_end: 28 }] };
const snapT = S.snapshot({ ...base }, 200);
const ti = TI.simulate({ rho: 2.0, Emax: 6, r: 0.03, T0: 80, e0: 1 }, snapT, S.defaultPlan(), {}, 120);
const sigT = { car_expansion: { grid: ti.days, values: ti.E.map(v => v / TI.POP.Eref) } };
const rec = M.simulate(truth, snapT, S.defaultPlan(), { signals: sigT }, 120);
const rng = GL.util.rng(5);
for (let i = 0; i < rec.days.length; i++) {
  const d = rec.days[i];
  if (d < -5 || d > 90) continue;
  if (d <= 14 || d % 2 === 0) { base.observations.push({ day: d, variable: 'anc', value: +(rec.anc[i] * Math.exp(0.2 * rng.normal())).toFixed(2) }); base.observations.push({ day: d, variable: 'plt', value: Math.round(rec.plt[i] * Math.exp(0.2 * rng.normal())) }); }
  if (d <= 28 && d % 2 === 0) base.observations.push({ day: d, variable: 'crp', value: +(rec.crp[i] * Math.exp(0.3 * rng.normal())).toFixed(1) });
}
for (const d of [-7, 0, 3, 7, 10, 14, 21, 28]) { const i = ti.days.indexOf(d); if (i >= 0 && d >= 0) base.observations.push({ day: d, variable: 'car_copies', value: +(ti.E[i] * Math.exp(0.3 * rng.normal())).toFixed(3) }); }
base.observations.push({ day: -6, variable: 'tumor_burden', value: 85 }); base.observations.push({ day: 30, variable: 'tumor_burden', value: +(ti.T[ti.days.indexOf(30)] * 1.1).toFixed(1) });
console.log('truth phenotype:', S.classifyPhenotype(rec.days, rec.anc), ' ANC:', [0,3,7,14,21,28,35,42,50,60,75,90].map(d => d + ':' + rec.anc[rec.days.indexOf(d)].toFixed(2)).join(' '), ' CRPmax', Math.max(...rec.crp).toFixed(0));
(async () => {
  for (const asOf of [-5, 7, 21, 42]) {
    const v = await GL.orchestrator.buildVersion(base, asOf, { nParticles: 500, nForecast: 80 });
    const m = v.modules.marrow, soc = v.plans.soc.outcomes.marrow;
    console.log(`asOf ${asOf}: ${v.computeMs} ms  nObs=${m.nObs} ess=${m.ess} beta=${m.beta}  R=${m.params.R.median.toFixed(2)} [${m.params.R.lo.toFixed(2)},${m.params.R.hi.toFixed(2)}] g=${m.params.g.median.toFixed(0)} q=1/${(1/m.params.q.median).toFixed(0)} f0=${m.params.f0.median.toFixed(3)}  SOC: quick=${soc.p_quick.value.toFixed(2)} sw=${soc.p_second_wave.value.toFixed(2)} pers=${soc.p_persistent.value.toFixed(2)}  TI: resp=${v.plans.soc.outcomes.tumor_immune.p_response.value.toFixed(2)} peak=${v.plans.soc.outcomes.tumor_immune.peak_expansion.value.toFixed(2)}`);
    console.log('   ranking:', v.ranking.map(id => id + '=' + v.plans[id].score.toFixed(3)).join('  '));
  }
})();
